import openpyxl, os, re

path='/root/glass_demand_sheet.xlsx'
wb=openpyxl.load_workbook(path, data_only=True)
print('Sheets:', wb.sheetnames)
ws=wb['Glass']

hits=[]
for r in range(1, ws.max_row+1):
    for c in range(1, ws.max_column+1):
        v=ws.cell(row=r,column=c).value
        if isinstance(v,str) and v and 'glass furnace demand' in v.lower():
            hits.append((r,c,v))

print('Exact substring hits count:', len(hits))
for h in hits[:20]:
    print(h)

# broader: any cell containing both 'glass' and 'demand'
broad=[]
for r in range(1, ws.max_row+1):
    row_vals=[]
    for c in range(1, min(ws.max_column, 30)+1):
        v=ws.cell(row=r,column=c).value
        if isinstance(v,str) and v:
            row_vals.append(v)
    joined=' | '.join(row_vals).lower()
    if 'glass' in joined and 'demand' in joined:
        broad.append((r, joined[:200]))

print('\nBroad row hits (glass & demand) count:', len(broad))
for r, snippet in broad[:30]:
    print(r, snippet)

# print first 20 rows first 10 cols to inspect
print('\nTop 25 rows, first 12 cols:')
for r in range(1, 26):
    vals=[ws.cell(row=r,column=c).value for c in range(1,13)]
    if any(v is not None and str(v).strip()!='' for v in vals):
        print(r, vals)
